package hack

import (
	"testing"
)

func TestMutableString(t *testing.T) {
	m := MutableString("hello")
	if m != "hello" {
		t.Errorf("MutableString(\"hello\") = %q, want %q", m, "hello")
	}
}

func TestString(t *testing.T) {
	b := []byte("hello")
	m := String(b)
	if m != MutableString("hello") {
		t.Errorf("String(%q) = %q, want %q", b, m, MutableString("hello"))
	}
}

func TestSlice(t *testing.T) {
	m := MutableString("hello")
	s := Slice(m)
	if s != []byte("hello") {
		t.Errorf("Slice(%q) = %q, want %q", m, s, []byte("hello"))
	}
}

func TestEstimateBucketMemoryUsage(t *testing.T) {
	tests := []struct {
		K, V comparable
		want uint64
	}{
		{int32(1), int64(1), DefBucketMemoryUsageForMapIntToPtr},
		{int32(1), struct{}{}, DefBucketMemoryUsageForMapIntToPtr},
		{int32(1), float64(1), DefBucketMemoryUsageForMapStringToAny},
		{int32(1), string("hello"), DefBucketMemoryUsageForMapStringToAny},
		{struct{}{}, struct{}{}, DefBucketMemoryUsageForMapStringToAny},
		{struct{}{}, string("hello"), DefBucketMemoryUsageForMapStringToAny},
		{string("hello"), string("hello"), DefBucketMemoryUsageForMapStringToAny},
		{string("hello"), struct{}{}, DefBucketMemoryUsageForMapStringToAny},
		{string("hello"), string("hello"), DefBucketMemoryUsageForSetString},
		{string("hello"), struct{}{}, DefBucketMemoryUsageForSetString},
		{string("hello"), float64(1), DefBucketMemoryUsageForSetFloat64},
		{string("hello"), string("hello"), DefBucketMemoryUsageForSetFloat64},
		{string("hello"), string("hello"), DefBucketMemoryUsageForSetInt64},
		{string("hello"), struct{}{}, DefBucketMemoryUsageForSetInt64},
	}

	for _, tt := range tests {
		got := EstimateBucketMemoryUsage(tt.K, tt.V)
		if got != tt.want {
			t.Errorf("EstimateBucketMemoryUsage(%T, %T) = %d, want %d", tt.K, tt.V, got, tt.want)
		}
	}
}

